if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/course/lib.php');
try {
    global $DB, $USER, $CFG;
    $USER = get_admin();

    // Create the demo category and course from PHP so the setup is self-contained.
    $category = $DB->get_record('course_categories', ['name' => 'Demo Courses']);
    if (!$category) {
        $category = \core_course_category::create((object) ['name' => 'Demo Courses']);
    }
    $categoryid = is_object($category) ? $category->id : $category;

    $course = $DB->get_record('course', ['shortname' => 'snap-demo']);
    if (!$course) {
        $course = create_course((object) [
            'fullname' => 'Snap Theme Demo',
            'shortname' => 'snap-demo',
            'category' => $categoryid,
            'format' => 'topics',
            'numsections' => 3,
            'summary' => 'Demo course used to showcase the Snap theme rendering on real Moodle content.',
            'summaryformat' => FORMAT_HTML,
        ]);
    }

    // Enrol the admin as editing teacher so the course shows up in "My courses".
    $manual = enrol_get_plugin('manual');
    $manualinstance = null;
    foreach (enrol_get_instances($course->id, false) as $inst) {
        if ($inst->enrol === 'manual') {
            $manualinstance = $inst;
            break;
        }
    }
    if (!$manualinstance && $manual) {
        $manualid = $manual->add_default_instance($course);
        $manualinstance = $manualid ? $DB->get_record('enrol', ['id' => $manualid]) : null;
    }
    $teacherrole = $DB->get_record('role', ['shortname' => 'editingteacher']);
    if ($manual && $manualinstance && $teacherrole) {
        $manual->enrol_user($manualinstance, $USER->id, $teacherrole->id);
    }

    // Add a Page activity with rich content so the course page has something for
    // the Snap theme to render (typography, headings, lists, blockquotes).
    $moduleid = $DB->get_field('modules', 'id', ['name' => 'page'], MUST_EXIST);
    if (!$DB->record_exists('page', ['course' => $course->id, 'name' => 'Welcome to the Snap demo'])) {
        $content = '<h2>Welcome to the Snap theme demo</h2>'
            . '<p>Snap redesigns the Moodle experience with a clean, card-based course layout, a slide-out '
            . 'personal menu and a focus on your learning activities and content. This whole site is rendered '
            . 'with the <strong>Snap</strong> theme.</p>'
            . '<h3>Things to try</h3>'
            . '<ul>'
            . '<li>Open the <strong>personal menu</strong> (top-left) to see courses, deadlines and messages.</li>'
            . '<li>Browse this course to see Snap\'s section cards and table of contents.</li>'
            . '<li>Visit <em>Site administration &rarr; Appearance &rarr; Snap settings</em> to explore the theme options.</li>'
            . '</ul>'
            . '<blockquote><p>Snap makes online learning an enjoyable and intuitive experience for learners and educators.</p></blockquote>';

        $pagerec = (object) [
            'course' => $course->id,
            'name' => 'Welcome to the Snap demo',
            'intro' => '<p>An introduction to this Snap theme demo course.</p>',
            'introformat' => FORMAT_HTML,
            'content' => $content,
            'contentformat' => FORMAT_HTML,
            'legacyfiles' => 0,
            'display' => 5,
            'displayoptions' => '',
            'revision' => 1,
            'timemodified' => time(),
        ];
        $pagerec->id = $DB->insert_record('page', $pagerec);

        $newcm = (object) [
            'course' => $course->id,
            'module' => $moduleid,
            'instance' => $pagerec->id,
            'section' => 1,
            'added' => time(),
            'visible' => 1,
            'visibleoncoursepage' => 1,
            'visibleold' => 1,
            'groupmode' => 0,
            'groupingid' => 0,
        ];
        $cmid = add_course_module($newcm);
        course_add_cm_to_section($course->id, $cmid, 1);
        rebuild_course_cache($course->id, true);
    }

    if (!$DB->record_exists('course', ['shortname' => 'snap-demo'])) {
        throw new \RuntimeException("The 'snap-demo' course is missing after provisioning.");
    }

    echo "Provisioned Snap theme demo on course 'snap-demo'.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'Snap theme demo provisioning failed: ' . $e->getMessage() . "\n");
}
